import datetime, json, re, subprocess

def read(args):
    try:
        p = subprocess.run(['/usr/bin/systemctl', *args], capture_output=True, text=True, timeout=2, check=False)
        return p.stdout if p.returncode == 0 and len(p.stdout) <= 16384 else None
    except (OSError, subprocess.SubprocessError):
        return None

raw = read(['list-units', '--all', '--type=service', '--plain', '--no-legend', '--no-pager', '*openclaw*'])
packet = {'schemaVersion': 1, 'source': 'systemd', 'observedAt': datetime.datetime.now(datetime.timezone.utc).isoformat(), 'state': 'unverified', 'matchedCount': 0, 'inspectedCount': 0, 'truncated': False, 'services': [], 'whatsapp': 'not_checked'}
if raw is not None:
    units = []
    parse_complete = True
    for line in raw.splitlines():
        fields = line.split()
        if fields and re.fullmatch(r'[-A-Za-z0-9_.@]+[.]service', fields[0]) and 'openclaw' in fields[0].lower():
            units.append(fields[0])
        elif fields:
            parse_complete = False
    units = sorted(set(units))
    packet['matchedCount'] = len(units)
    packet['truncated'] = len(units) > 5
    for unit in units[:5]:
        output = read(['show', unit, '--property=LoadState,ActiveState,SubState,UnitFileState,Restart', '--no-pager'])
        if output is None:
            continue
        values = dict(line.split('=', 1) for line in output.splitlines() if '=' in line)
        allowed = {
            'load': ('LoadState', ['loaded', 'error', 'not-found', 'bad-setting', 'masked', 'stub', 'merged']),
            'active': ('ActiveState', ['active', 'reloading', 'inactive', 'failed', 'activating', 'deactivating', 'maintenance', 'refreshing']),
            'sub': ('SubState', ['running', 'dead', 'exited', 'failed', 'auto-restart', 'start', 'start-pre', 'start-post', 'stop', 'stop-sigterm', 'stop-sigkill', 'stop-post', 'final-sigterm', 'final-sigkill', 'reload']),
            'enabled': ('UnitFileState', ['enabled', 'enabled-runtime', 'disabled', 'static', 'indirect', 'masked', 'masked-runtime', 'generated', 'transient', 'linked', 'linked-runtime', 'alias', 'bad']),
            'restart': ('Restart', ['no', 'always', 'on-success', 'on-failure', 'on-abnormal', 'on-watchdog', 'on-abort'])
        }
        packet['services'].append({key: values.get(prop) if values.get(prop) in choices else 'unknown' for key, (prop, choices) in allowed.items()})
    packet['inspectedCount'] = len(packet['services'])
    if parse_complete and packet['inspectedCount'] == packet['matchedCount'] and not packet['truncated']:
        packet['state'] = 'observed'
    packet['observedAt'] = datetime.datetime.now(datetime.timezone.utc).isoformat()
print(json.dumps(packet, separators=(',', ':')))
